export function decodeGeneratingV2Frames(): Uint8Array {
  const binary = globalThis.atob(GENERATING_V2_FRAMES_B64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
